"""
Pages Batch 2 (Canvases 13-24, Prelim. Fol. 4r-9v) for Wellcome MS.244.
Covers the remaining preliminary leaves:
  - Canvas 13 (Fol. 4r): Apothecary Weights & Measures (dated 10 August 1564) and Henry Dineley's 'H.D.' attestation
  - Canvas 14 (Fol. 4v): Pen-and-ink Sundial / Astronomical Quadrant Diagram
  - Canvas 15 (Fol. 5r): Blank ruled calendar grid (folio '5') with bleed-through from 5v
  - Canvas 16 (Fol. 5v): Calendar table (Jan 1-4, Circumcision, 1613) & Dineley coat of arms
  - Canvas 17 (Fol. 6r): Poultices ('Pultesses Cum to my hands...', nos. 1-18)
  - Canvas 18 (Fol. 6v): Poultices ('Pultesses', nos. 1-15)
  - Canvas 19 (Fol. 7r): Poultices ('Pultesses', nos. 16-34)
  - Canvas 20 (Fol. 7v): Poultices (nos. 34-48)
  - Canvas 21 (Fol. 8r): Remedies 'Out of Leonard Phiorauant' (Petra Philosophale, Balme, Aromatico, Electuario Angelica)
  - Canvas 22 (Fol. 8v): Fioravanti continued (Sirupo Solutivo, Sirupo Magistrale, Oleum Philosophorum, Sublimate water)
  - Canvas 23 (Fol. 9r): 'Halchimy Anselmi Boetius' (Lapis Lazuli, Lapis Armenus, Tinctura Coralli)
  - Canvas 24 (Fol. 9v): Anselmus Boëtius continued (Tinctura & Essentia Corallorum, De Succino / Amber)
"""


def make_lines(prefix, canvas_num, col_id, ulx, uly, lrx, lry, line_tuples):
    n = len(line_tuples)
    step = (lry - uly) / max(1, n)
    img_svc = f"https://iiif.wellcomecollection.org/image/b19608652_MS_244_{canvas_num:04d}.JP2"
    canvas_uri = f"https://iiif.wellcomecollection.org/presentation/b19608652/canvases/b19608652_MS_244_{canvas_num:04d}.JP2"
    out = []
    for idx, (lno, ltype, orig_text, en_text, note) in enumerate(line_tuples):
        y0 = int(round(uly + idx * step))
        y1 = int(round(uly + (idx + 1) * step))
        w = lrx - ulx
        h = y1 - y0
        xywh = f"{ulx},{y0},{w},{h}"
        line_id = f"{prefix}_{col_id}_l{lno:02d}" if isinstance(lno, int) else f"{prefix}_{col_id}_{lno}"
        out.append({
            "line_id": line_id,
            "line_num": str(lno),
            "line_type": ltype,
            "ulx": ulx,
            "uly": y0,
            "lrx": lrx,
            "lry": y1,
            "xywh": xywh,
            "iiif_canvas_xywh": f"{canvas_uri}#xywh={xywh}",
            "iiif_image_crop": f"{img_svc}/{xywh}/full/0/default.jpg",
            "orig": orig_text,
            "en": en_text,
            "note": note,
        })
    return out


