                    (24, "body", "Corpus in temperiem redigit celesti quadam ui,", "It brings the body into temper by a certain celestial power,", ""),
                    (25, "body", "ac propterea omnes per totu[m] internoru[m] affectus", "and therefore removes all internal affections", ""),
                    (26, "body", "radicitus abellat, propter analogiam quand[am]", "by the roots, because of a certain analogy", ""),
                    (27, "body", "habet in spiritib[us] vitalib[us] & callido innato, quo", "it has with the vital spirits and innate heat, which", ""),
                    (28, "body", "auget & roborat ut facile contrarios morbos", "it increases and strengthens so that it may easily", ""),
                    (29, "body", "sugere possit /", "overcome contrary diseases.", ""),
                    (30, "body", "Morbu[m] comitialem, presertim si Spiritu vitrioli", "It is reported to cure epilepsy completely in a few weeks,", ""),
                    (31, "body", "preparata fuerit, paucis Septimanis prorsus", "especially if prepared with spirit of vitriol,", ""),
                    (32, "body", "tollere perhibetur, etiamsi a funestibus quib[us] da[m] laborarit .", "even if one has laboured under it from fatal causes.", ""),
                    (33, "body", "Propterea comendatur tinctura ad solera fluore[m]", "Therefore the tincture is commended for", ""),
                    (34, "body", "albos & rubros, quos ita sistit ut nullu[m] aliud", "white and red fluxes, which it stops so that no other", ""),
                    (35, "body", "med[icamen]tu[m] melius infirmorum menar[um] uxarit, omne etia[m]", "medicine better...; it also restrains all", ""),
                    (36, "body", "alui & sanguinis profluuiu[m] ex quacunq[ue] p[ar]te profluat compescit .", "flux of the belly and of blood from whatever part it flows.", ""),
                    (37, "body", "Gonorream etiam seroq[ue] diuturna[m] sanat,", "It also heals chronic gonorrhoea,", ""),
                    (38, "body", "longe efficacius & minori p[er]iculo, qua[m] puluis ex corallis preparatis .", "far more efficaciously and with less danger than powder of prepared coral.", ""),
                    (39, "body", "Gall[ico] pestiferis in poma foriano aut aqua ard[ente]", "In the French pox or plague, in...", ""),
                    (40, "body", "cu[m] fe[r]o si adest febris mirabile succursu[m] exhibetur", "if fever is present it gives wonderful succour.", ""),
                    (41, "body", "Diarrheis aut disenterijs pestilentib[us] non minus eadem dosi medetur .", "Pestilent diarrhoeas or dysenteries are no less cured by the same dose.", ""),
                    (42, "heading", "Ad malancholiam & tympanitidem", "For melancholy and tympanites", ""),
                    (43, "body", "℞ corallor[um] ℥ iij, croci orient[alis] iiij, Hipericonis ana ℥ iij", "Take coral 3 oz., oriental saffron 4, St John's wort of each 3 oz.,", ""),
                    (44, "body", "Storac[is] callamite, laudani ana ℥ β, sp[iritus] v[ini] cand[idi]", "storax calamita, labdanum of each ½ oz., white spirit of wine", ""),
                    (45, "body", "li ij, coquantur simul in cucurbita vitrea 24", "2 lb; boil together in a glass cucurbit 24", ""),
                    (46, "body", "horas, postea exhallet ne fumos ac inde effundatur", "hours, then let the fumes exhale and pour off;", ""),
                    (47, "body", "ita coralli fiunt duri & rubri, hos in mortario con=", "thus the corals become hard and red; pound them in a mortar", ""),
                    (48, "body", "tunde & tere supra porphiriu[m] ac exigit ex sex in aqua suptamb ad predicta", "and grind on porphyry...", ""),
                    (49, "heading", "Liquor corallor[um] ad omnes p[rae]dictos effectus", "Liquor of corals for all aforesaid effects", ""),
                    (50, "body", "℞ Corallos grosso modo contusos solue in aceto", "Take coarsely bruised corals, dissolve in strong", ""),
                    (51, "body", "vehementi ac solutos digere p[er] mensem, ita tinget[ur]", "vinegar and digest the dissolved [corals] for a month; thus the", ""),
                    (52, "body", "acetu[m], quod effunde aliudq[ue] affunde, donec non", "vinegar is tinged, which pour off and pour on more until", ""),
                    (53, "body", "amplius coloretur . postea filtra effusa, & leni", "it is coloured no more. Then filter what was poured off, and with gentle", ""),
                    (54, "body", "igni euaporet omne, residentia ablue, exicca,", "fire evaporate all, wash the residue, dry,", ""),
                    (55, "body", "ac in spiritu vini rectica, postea distilla, ac", "and rectify in spirit of wine, then distill, and", ""),
                    (56, "body", "postremo supra marmor solue, ita habebis", "lastly dissolve upon marble; thus you shall have", ""),
                    (57, "body", "veru[m] liquorem, cuius propina sex aut octo", "the true liquor, of which give 6 or 8", ""),
                    (58, "body", "guttas in conuenienti liquore ad omnia dicta mala .", "drops in a convenient liquor for all said evils.", ""),
                    (59, "body", "lost out in pill[es] de lapide Armonio to begi[n] after qualitatem . * at this marke *", "Left out in Pills of Lapis Armenus to begin after 'qualitatem' at this mark *.", "English scribal note at foot."),
                    (60, "body", "* Si uero paucis potionis forma sumere nolit, in pillulas redige debet addita Hiere picre q[uantum] s[ufficit] uel alio electuario alui beneficio promouente sic modo ℞ Hiere picre ℥ β ut ante and it must end at tho[se]", "If one will not take it in potion form, it ought to be reduced into pills with hiera picra q.s. or another electuary...", "Omitted Latin passage added at foot."),
