                    (11, "body", "distillatione phlegma sequi : sinab[is] in digestione", "distillation; leave in digestion", ""),
                    (12, "body", "p[er] biduu[m], ita Spiritus colorem extrahit rubeu[m]", "for two days; thus the spirit extracts the red colour,", ""),
