                    (23, "body", "sit addito sale uel oleo Salis", "with salt or oil of salt added.", ""),
                    (24, "body", "Alij primo pure in spiritu vini soluunt, succinu[m]", "Others first dissolve it pure in spirit of wine,", ""),
