                    (26, "body", "Alij in aceto forti uel distillato", "Others in strong or distilled vinegar.", ""),
                    (27, "body", "Alij p[er] lento igne distillant ac postea repetit[a] distillatione p[er] Balneu[m] rectificant", "Others distill by slow fire and afterwards rectify by repeated distillation in a water-bath.", ""),
                    (28, "heading", "A mult[is] hic modus celebratur", "This method is celebrated by many", ""),
                    (29, "body", "℞ fragmenta Succini non subtiliter pulu[erizata]", "Take fragments of amber not finely powdered", ""),
                    (30, "body", "li j . adde pulueris silicu[m] calcimator[um] aut arene", "1 lb, add powder of calcined flints or clean", ""),
                    (31, "body", "munde li iij imponat[ur] Retorte lutate eameque", "sand 3 lb; put in a luted retort and place", ""),
                    (32, "body", "furno praelo remitte luto, adecto vitro reci=", "it in the furnace with a glass receiver", ""),
